// NEGATIVE CONTROL (RWF-013/RWF-025 semantics): the alias is REASSIGNED
// before the export write, so its initializer is stale. What this package
// publishes as "vulnerable" is `harmless`, never `dangerous`. Binding the
// advisory target to the stale initializer would be a false target.
var impl = require("./impl");
var alias = impl.dangerous;
alias = impl.harmless;

module.exports.vulnerable = alias;
